text:
{
  "questions": [
    {
      "n": 1,
      "start": "Un bilan du projet « sport-Santé » a t-il été réalisé ?",
      "end": "Si oui, quels en sont les constats principaux ?"
    },
    {
      "n": 2,
      "start": "Le projet étant prévu jusqu'à fin 2018, le Conseil d'Etat pense-t-il le reconduire ?",
      "end": ""
    },
    {
      "n": 3,
      "start": "Comment a été faite la communication de ce projet ?",
      "end": ""
    },
    {
      "n": 4,
      "start": "Qui choisit les projets ou activités à soutenir ?",
      "end": ""
    },
    {
      "n": 5,
      "start": "Comment se fait le suivi des projets ou activités ?",
      "end": ""
    },
    {
      "n": 6,
      "start": "Le Conseil d'Etat pense-t-il aouter un axe d'intervention financière supplémentaire",
      "end": "notamment pour soutenir les communes qui souhaitent engager des ressources humaines pour atteindre l'objectif fixé par le projet Sport-Santé ?"
    }
  ],
  "answers": [
    {
      "n": 1,
      "start": "Comme prévu dans le planning du projet, un bilan a été effectué à mi-2018.",
      "end": "nous avons noté une augmentation progressive des projets en termes de nombre et de répartition géographique"
    },
    {
      "n": 2,
      "start": "Oui, le Conseil d’Etat en cohérence avec le RPS 2018-2022 va continuer à soutenir ce projet.",
      "end": ""
    },
    {
      "n": 3,
      "start": "La communication s’est déroulée en plusieurs étapes : lors du lancement du projet, une page internet",
      "end": "décrivant les conditions d’octroi du financement a été créée sur le site de l’Etat et un courrier a été adressé à l’ensemble des communes du Canton."
    },
    {
      "n": 4,
      "start": "Suite aux travaux préparatoires au projet « Sport-Santé », une priorisation d’actions a été faite par les deux",
      "end": "départements directement concernés, le DEIS et le DSAS."
    },
    {
      "n": 5,
      "start": "Une fois la décision prise de soutenir un projet, l’entité requérante reçoit un courrier annonçant le montant de",
      "end": "l’aide financière accordée (sur la base des modalités d’octroi) ainsi qu’une convention de financement."
    },
    {
      "n": 6,
      "start": "L’objectif de ce projet est de permettre à la population de pratiquer un sport pour le plaisir, une activité",
      "end": "physique sans notion de performance ou de sélection avec des conditions accessibles."
    }
  ],
  "submitter": "Romano-Malagrifa Myriam",
  "co_signatories": [],
  "recommendation": "none",
  "reasoning": {
    "start": "Le maintien en santé de la population est une préoccupation constante du Conseil d’Etat : à ce titre il est",
    "end": "déterminé à intervenir dans plusieurs politiques publiques."
  }
}
